import type { Metadata } from "next";
import { Outfit } from "next/font/google";
import "./globals.css";
import { Providers } from "./providers";

const outfit = Outfit({
  subsets: ["latin"],
  variable: "--font-outfit",
});

export const metadata: Metadata = {
  title: "Eterna — Digital Afterlife & Inheritance",
  description:
    "Secure your digital legacy. Eterna is an AI-powered digital inheritance executor that distributes your crypto assets to loved ones — automatically and trustlessly.",
  openGraph: {
    title: "Eterna — Digital Afterlife",
    description: "AI-powered crypto inheritance executor",
  },
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" className="h-full">
      <body
        className={`${outfit.className} ${outfit.variable} min-h-full flex flex-col bg-[#0c0c0c] text-[#f5f5f5] antialiased`}
      >
        <div className="grain-overlay" aria-hidden="true" />
        <Providers>{children}</Providers>
      </body>
    </html>
  );
}

