import { ethers } from "ethers";
import { config } from "./config.js";

// EternaWill ABI — minimal subset for AI Agent operations
const ETERNA_WILL_ABI = [
  "function getWill(uint256 _willId) view returns (tuple(address owner, bytes32 encryptedDataHash, uint8 status, tuple(uint256 inactivityPeriod, uint256 guardianThreshold, uint256 minGuardians, bool useOracle) triggerConfig, uint256 lastHeartbeat, uint256 createdAt, uint256 executedAt))",
  "function getBeneficiaries(uint256 _willId) view returns (tuple(string name, address wallet, uint256 percentage, uint256 delaySeconds, bool claimed)[])",
  "function getGuardians(uint256 _willId) view returns (tuple(address wallet, string name, bool hasVoted, bool vote, uint256 votedAt)[])",
  "function getGuardianVoteStatus(uint256 _willId) view returns (uint256 votesFor, uint256 total)",
  "function getWillStatus(uint256 _willId) view returns (uint8 status, uint256 lastHeartbeat, uint256 inactivityScore, uint256 guardianScore, uint256 guardianVotesFor, uint256 totalGuardians)",
  "function checkExecutable(uint256 _willId) view returns (bool canExecute, uint256 confidenceScore)",
  "function executeWill(uint256 _willId)",
  "function distributeETH(uint256 _willId)",
  "function distributeERC20(uint256 _willId, address _token)",
  "function checkIn(uint256 _willId)",
  "function totalWills() view returns (uint256)",
  "function getOwnerWills(address _owner) view returns (uint256[])",
  "event WillCreated(uint256 indexed willId, address indexed owner, bytes32 encryptedDataHash)",
  "event WillExecuted(uint256 indexed willId, uint256 timestamp)",
  "event Heartbeat(uint256 indexed willId, address indexed owner, uint256 timestamp)",
  "event GuardianVoted(uint256 indexed willId, address indexed guardian, bool vote, uint256 timestamp)",
];

export interface WillData {
  willId: number;
  owner: string;
  status: number; // 0=Active, 1=Executed, 2=Revoked
  lastHeartbeat: number;
  inactivityPeriod: number;
  guardianThreshold: number;
  totalGuardians: number;
  guardianVotesFor: number;
  inactivityScore: number;
  guardianScore: number;
}

export interface BeneficiaryData {
  name: string;
  wallet: string;
  percentage: number;
  delaySeconds: number;
  claimed: boolean;
}

let provider: ethers.JsonRpcProvider;
let signer: ethers.Wallet;
let contract: ethers.Contract;

export function initContract() {
  provider = new ethers.JsonRpcProvider(config.rpcUrl);
  signer = new ethers.Wallet(config.privateKey, provider);
  contract = new ethers.Contract(config.contractAddress, ETERNA_WILL_ABI, signer);
  console.log(`[Contract] Connected to ${config.contractAddress} via ${config.rpcUrl}`);
}

export function getContract(): ethers.Contract {
  return contract;
}

export function getProvider(): ethers.JsonRpcProvider {
  return provider;
}

export function getSigner(): ethers.Wallet {
  return signer;
}

/**
 * Fetch all active wills and return their execution readiness
 */
export async function scanActiveWills(): Promise<{ willId: number; executable: boolean; confidence: number }[]> {
  try {
    const totalWills = Number(await contract.totalWills());
    console.log(`[Scan] Total wills: ${totalWills}`);

    const results: { willId: number; executable: boolean; confidence: number }[] = [];

    for (let i = 0; i < totalWills; i++) {
      try {
        const will = await contract.getWill(i);
        const status = Number(will.status);

        // Skip executed or revoked wills
        if (status !== 0) continue;

        const [canExecute, confidence] = await contract.checkExecutable(i);
        results.push({
          willId: i,
          executable: canExecute,
          confidence: Number(confidence),
        });
      } catch (err) {
        console.error(`[Scan] Error checking will ${i}:`, err);
      }
    }

    return results;
  } catch (err) {
    console.error("[Scan] Error scanning wills:", err);
    return [];
  }
}

/**
 * Execute will on-chain
 */
export async function executeWill(willId: number): Promise<boolean> {
  try {
    const tx = await contract.executeWill(willId, {
      gasLimit: config.agent.executionGasLimit,
    });
    console.log(`[Execute] Will ${willId} tx: ${tx.hash}`);
    const receipt = await tx.wait();
    console.log(`[Execute] Will ${willId} confirmed in block ${receipt.blockNumber}`);
    return true;
  } catch (err) {
    console.error(`[Execute] Failed to execute will ${willId}:`, err);
    return false;
  }
}

/**
 * Distribute ETH from executed will
 */
export async function distributeETH(willId: number): Promise<boolean> {
  try {
    const tx = await contract.distributeETH(willId, {
      gasLimit: config.agent.executionGasLimit,
    });
    console.log(`[Distribute] Will ${willId} ETH tx: ${tx.hash}`);
    const receipt = await tx.wait();
    console.log(`[Distribute] Will ${willId} ETH distributed in block ${receipt.blockNumber}`);
    return true;
  } catch (err) {
    console.error(`[Distribute] Failed to distribute ETH for will ${willId}:`, err);
    return false;
  }
}

/**
 * Get beneficiary details for notification
 */
export async function getBeneficiaryDetails(willId: number): Promise<BeneficiaryData[]> {
  try {
    const beneficiaries = await contract.getBeneficiaries(willId);
    return beneficiaries.map((b: any) => ({
      name: b.name,
      wallet: b.wallet,
      percentage: Number(b.percentage),
      delaySeconds: Number(b.delaySeconds),
      claimed: b.claimed,
    }));
  } catch (err) {
    console.error(`[Beneficiaries] Error fetching will ${willId}:`, err);
    return [];
  }
}

/**
 * Get will status details
 */
export async function getWillData(willId: number): Promise<WillData | null> {
  try {
    const status = await contract.getWillStatus(willId);
    const will = await contract.getWill(willId);
    return {
      willId,
      owner: will.owner,
      status: Number(status.status),
      lastHeartbeat: Number(status.lastHeartbeat),
      inactivityPeriod: Number(will.triggerConfig.inactivityPeriod),
      guardianThreshold: Number(will.triggerConfig.guardianThreshold),
      totalGuardians: Number(status.totalGuardians),
      guardianVotesFor: Number(status.guardianVotesFor),
      inactivityScore: Number(status.inactivityScore),
      guardianScore: Number(status.guardianScore),
    };
  } catch (err) {
    console.error(`[WillData] Error fetching will ${willId}:`, err);
    return null;
  }
}

/**
 * Register heartbeat
 */
export async function sendHeartbeat(willId: number, privateKey: string): Promise<boolean> {
  try {
    const ownerSigner = new ethers.Wallet(privateKey, provider);
    const ownerContract = new ethers.Contract(config.contractAddress, ETERNA_WILL_ABI, ownerSigner);
    const tx = await ownerContract.checkIn(willId);
    await tx.wait();
    return true;
  } catch (err) {
    console.error(`[Heartbeat] Failed for will ${willId}:`, err);
    return false;
  }
}

