import { config } from "./config.js";
import { scanActiveWills, executeWill, distributeETH, getWillData, getBeneficiaryDetails } from "./contract.js";
import { notifyBeneficiary } from "./notifications.js";

// Track last processed status to avoid duplicate notifications
const processedWills = new Set<number>();

/**
 * AI Agent main loop — called by cron every pollIntervalMs
 */
export async function agentTick(): Promise<void> {
  console.log("[Agent] Tick start — scanning for executable wills...");

  try {
    const activeWills = await scanActiveWills();
    console.log(`[Agent] Found ${activeWills.length} active wills`);

    for (const will of activeWills) {
      if (will.executable && !processedWills.has(will.willId)) {
        console.log(`[Agent] Will ${will.willId} is EXECUTABLE (confidence: ${(will.confidence / 100).toFixed(1)}%)`);

        // Step 1: Execute will on-chain
        const executed = await executeWill(will.willId);
        if (!executed) {
          console.error(`[Agent] Failed to execute will ${will.willId} — skipping`);
          continue;
        }

        // Step 2: Distribute ETH
        const distributed = await distributeETH(will.willId);
        if (!distributed) {
          console.error(`[Agent] Failed to distribute ETH for will ${will.willId}`);
          // Continue anyway — assets might be claimable later
        }

        // Step 3: Notify beneficiaries
        const beneficiaries = await getBeneficiaryDetails(will.willId);
        for (const ben of beneficiaries) {
          try {
            await notifyBeneficiary({
              willId: will.willId,
              name: ben.name,
              wallet: ben.wallet,
              percentage: ben.percentage,
            });
          } catch (err) {
            console.error(`[Agent] Failed to notify ${ben.name}:`, err);
          }
        }

        // Step 4: Log via AI analysis
        await logExecutionToAI(will.willId);

        processedWills.add(will.willId);
        console.log(`[Agent] Will ${will.willId} fully processed ✅`);
      }
    }

    if (activeWills.length === 0) {
      console.log("[Agent] No executable wills found");
    }
  } catch (err) {
    console.error("[Agent] Tick error:", err);
  }
}

/**
 * AI-powered execution logging — uses LLM to generate a summary
 */
async function logExecutionToAI(willId: number): Promise<void> {
  if (!config.openaiApiKey) {
    console.log(`[AI Log] No OpenAI API key configured — skipping AI analysis for will ${willId}`);
    return;
  }

  try {
    const willData = await getWillData(willId);
    if (!willData) return;

    // Dynamic import of OpenAI only when needed
    const { default: OpenAI } = await import("openai");
    const openai = new OpenAI({ apiKey: config.openaiApiKey });

    const completion = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        {
          role: "system",
          content: "You are Eterna's execution auditor. Summarize the will execution in 2-3 sentences.",
        },
        {
          role: "user",
          content: JSON.stringify({
            event: "WILL_EXECUTED",
            willId,
            inactivityScore: willData.inactivityScore,
            guardianScore: willData.guardianScore,
            totalGuardians: willData.totalGuardians,
            guardianVotesFor: willData.guardianVotesFor,
            lastHeartbeat: new Date(willData.lastHeartbeat * 1000).toISOString(),
          }),
        },
      ],
    });

    const summary = completion.choices[0]?.message?.content || "";
    console.log(`[AI Log] Will ${willId}: ${summary}`);
  } catch (err) {
    console.error(`[AI Log] Error for will ${willId}:`, err);
  }
}

/**
 * Get agent status summary
 */
export function getAgentStatus() {
  return {
    running: true,
    pollIntervalMs: config.agent.pollIntervalMs,
    confidenceThreshold: config.agent.confidenceThreshold,
    processedWills: Array.from(processedWills),
    processedCount: processedWills.size,
    contractAddress: config.contractAddress,
  };
}

import dotenv from "dotenv";
dotenv.config();

export const config = {
  port: parseInt(process.env.PORT || "3001", 10),
  rpcUrl: process.env.RPC_URL || "http://127.0.0.1:8545",
  contractAddress: process.env.CONTRACT_ADDRESS || "",
  privateKey: process.env.PRIVATE_KEY || "",
  openaiApiKey: process.env.OPENAI_API_KEY || "",
  sendgridApiKey: process.env.SENDGRID_API_KEY || "",
  fromEmail: process.env.FROM_EMAIL || "noreply@eterna.ai",
  baseUrl: process.env.BASE_URL || "http://localhost:3000",

  // AI Agent config
  agent: {
    pollIntervalMs: parseInt(process.env.AGENT_POLL_INTERVAL || "60000", 10),
    confidenceThreshold: parseInt(process.env.CONFIDENCE_THRESHOLD || "7000", 10),
    executionGasLimit: parseInt(process.env.EXECUTION_GAS_LIMIT || "500000", 10),
  },
};

