import { config } from "./config.js";

interface BeneficiaryNotification {
  willId: number;
  name: string;
  wallet: string;
  percentage: number;
}

/**
 * Send email notification using SendGrid (or console fallback)
 */
export async function notifyBeneficiary(data: BeneficiaryNotification): Promise<void> {
  const subject = `Important: Digital Inheritance Notification — Will #${data.willId}`;
  const body = generateEmailBody(data);

  if (config.sendgridApiKey) {
    await sendViaSendGrid(data, subject, body);
  } else {
    // Fallback: log to console
    console.log(`[Notification] === EMAIL TO BENEFICIARY ===`);
    console.log(`[Notification] To: ${data.name} (${data.wallet})`);
    console.log(`[Notification] Subject: ${subject}`);
    console.log(`[Notification] Body:\n${body}`);
    console.log(`[Notification] ===========================`);
  }
}

function generateEmailBody(data: BeneficiaryNotification): string {
  return `
Dear ${data.name},

This is an automated notification from Eterna — a digital inheritance service.

You have been designated as a beneficiary of a digital will (#${data.willId}).
The execution conditions of this will have been met, and the assets are
ready for distribution.

YOUR ALLOCATION:
• Will ID: ${data.willId}
• Your share: ${(data.percentage / 100).toFixed(1)}% of the estate

To claim your assets:
1. Visit: ${config.baseUrl}/claim/${data.willId}
2. Connect your wallet (${data.wallet})
3. Follow the on-screen instructions

Need help? Visit ${config.baseUrl}/support

This is an automated message from Eterna AI Agent.
Please keep this information secure.

— Eterna Team
`.trim();
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
let sgMail: any = null;

async function getSendGrid() {
  if (!sgMail) {
    // @ts-ignore - optional dependency
    sgMail = await import("@sendgrid/mail");
  }
  return sgMail;
}

async function sendViaSendGrid(
  data: BeneficiaryNotification,
  subject: string,
  body: string
): Promise<void> {
  try {
    const mail = await getSendGrid();
    mail.default.setApiKey(config.sendgridApiKey);

    await mail.default.send({
      to: data.wallet, // In production, use stored email
      from: config.fromEmail,
      subject,
      text: body,
    });

    console.log(`[SendGrid] Email sent to ${data.name} (${data.wallet})`);
  } catch (err) {
    console.error(`[SendGrid] Failed to send email:`, err);
    throw err;
  }
}

