import express from "express";
import cors from "cors";
import cron from "node-cron";
import { config } from "./config.js";
import { initContract } from "./contract.js";
import { agentTick } from "./agent.js";
import apiRouter from "./api.js";

const app = express();

// Middleware
app.use(cors());
app.use(express.json());

// API routes
app.use("/api", apiRouter);

// Health check
app.get("/", (_req, res) => {
  res.json({
    name: "Eterna Backend",
    version: "1.0.0",
    status: "running",
    agentPollIntervalMs: config.agent.pollIntervalMs,
  });
});

// Start server
async function start() {
  try {
    // Initialize contract connection
    if (config.contractAddress && config.privateKey) {
      initContract();
      console.log("[Startup] Contract initialized");

      // Start AI Agent cron job
      const cronExpression = `*/${Math.max(1, Math.floor(config.agent.pollIntervalMs / 60000))} * * * *`;
      cron.schedule(cronExpression, () => {
        agentTick().catch((err) => console.error("[Cron] Agent tick error:", err));
      });
      console.log(`[Startup] AI Agent cron scheduled: "${cronExpression}"`);

      // Run initial scan
      agentTick().catch((err) => console.error("[Startup] Initial scan error:", err));
    } else {
      console.warn("[Startup] CONTRACT_ADDRESS or PRIVATE_KEY not set — running in API-only mode");
      console.warn("[Startup] Set these env vars to enable AI Agent functionality");
    }

    app.listen(config.port, () => {
      console.log(`[Startup] Eterna Backend running on http://localhost:${config.port}`);
      console.log(`[Startup] API docs: http://localhost:${config.port}/api/status`);
    });
  } catch (err) {
    console.error("[Startup] Fatal error:", err);
    process.exit(1);
  }
}

start();

