import { Router, Request, Response } from "express";
import { getContract, getWillData, sendHeartbeat, getBeneficiaryDetails } from "./contract.js";
import { getAgentStatus } from "./agent.js";

const router = Router();

/**
 * GET /api/status — Health check & agent status
 */
router.get("/status", (_req: Request, res: Response) => {
  res.json({
    ok: true,
    service: "eterna-backend",
    agent: getAgentStatus(),
    timestamp: new Date().toISOString(),
  });
});

/**
 * GET /api/wills/:id — Get will details
 */
router.get("/wills/:id", async (req: Request, res: Response) => {
  try {
    const willId = parseInt(req.params.id, 10);
    if (isNaN(willId)) {
      return res.status(400).json({ error: "Invalid will ID" });
    }

    const data = await getWillData(willId);
    if (!data) {
      return res.status(404).json({ error: "Will not found" });
    }

    const beneficiaries = await getBeneficiaryDetails(willId);
    const contract = getContract();
    const guardians = await contract.getGuardians(willId);
    const will = await contract.getWill(willId);

    res.json({
      ...data,
      encryptedDataHash: will.encryptedDataHash,
      createdAt: Number(will.createdAt),
      executedAt: Number(will.executedAt),
      beneficiaries,
      guardians: guardians.map((g: any) => ({
        wallet: g.wallet,
        name: g.name,
        hasVoted: g.hasVoted,
        vote: g.vote,
        votedAt: Number(g.votedAt),
      })),
    });
  } catch (err) {
    console.error("[API] Error fetching will:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

/**
 * GET /api/wills/:id/beneficiaries — Get beneficiaries for a will
 */
router.get("/wills/:id/beneficiaries", async (req: Request, res: Response) => {
  try {
    const willId = parseInt(req.params.id, 10);
    if (isNaN(willId)) {
      return res.status(400).json({ error: "Invalid will ID" });
    }

    const beneficiaries = await getBeneficiaryDetails(willId);
    res.json({ willId, beneficiaries });
  } catch (err) {
    console.error("[API] Error fetching beneficiaries:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

/**
 * POST /api/wills/:id/heartbeat — Send heartbeat
 * Body: { "privateKey": "0x..." }
 */
router.post("/wills/:id/heartbeat", async (req: Request, res: Response) => {
  try {
    const willId = parseInt(req.params.id, 10);
    if (isNaN(willId)) {
      return res.status(400).json({ error: "Invalid will ID" });
    }

    const { privateKey } = req.body;
    if (!privateKey) {
      return res.status(400).json({ error: "privateKey is required" });
    }

    const success = await sendHeartbeat(willId, privateKey);
    if (success) {
      res.json({ ok: true, message: "Heartbeat registered" });
    } else {
      res.status(400).json({ error: "Failed to send heartbeat" });
    }
  } catch (err) {
    console.error("[API] Heartbeat error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

/**
 * GET /api/wills/owner/:address — Get wills for an owner
 */
router.get("/wills/owner/:address", async (req: Request, res: Response) => {
  try {
    const contract = getContract();
    const willIds = await contract.getOwnerWills(req.params.address);
    res.json({ owner: req.params.address, willIds: willIds.map(Number) });
  } catch (err) {
    console.error("[API] Error fetching owner wills:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

/**
 * GET /api/wills/:id/claim — Get claim info for beneficiary
 */
router.get("/wills/:id/claim", async (req: Request, res: Response) => {
  try {
    const willId = parseInt(req.params.id, 10);
    if (isNaN(willId)) {
      return res.status(400).json({ error: "Invalid will ID" });
    }

    const contract = getContract();
    const will = await contract.getWill(willId);
    const status = Number(will.status);

    if (status !== 1) {
      return res.json({
        willId,
        status: ["Active", "Executed", "Revoked"][status],
        claimable: false,
        message: "Will has not been executed yet.",
      });
    }

    const beneficiaries = await getBeneficiaryDetails(willId);
    const executedAt = Number(will.executedAt);
    const now = Math.floor(Date.now() / 1000);
    const claimDeadline = executedAt + 365 * 24 * 60 * 60; // 1 year

    res.json({
      willId,
      status: "Executed",
      executedAt: new Date(executedAt * 1000).toISOString(),
      claimable: now < claimDeadline,
      claimDeadline: new Date(claimDeadline * 1000).toISOString(),
      beneficiaries,
    });
  } catch (err) {
    console.error("[API] Error fetching claim info:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

