103	    // ============ Core Functions ============
104	
105	    /**
106	     * @notice Create a new digital will
107	     * @param _beneficiaries Array of beneficiary addresses
108	     * @param _percentages Array of percentages in basis points (50% = 5000)
109	     * @param _names Array of beneficiary names
110	     * @param _delaySeconds Array of time-lock delays (0 for immediate)
111	     * @param _guardians Array of guardian addresses
112	     * @param _guardianNames Array of guardian names
113	     * @param _triggerConfig Trigger configuration
114	     * @param _encryptedDataHash IPFS hash of encrypted will document
115	     */
116	    function createWill(
117	        address[] calldata _beneficiaries,
118	        uint256[] calldata _percentages,
119	        string[] calldata _names,
120	        uint256[] calldata _delaySeconds,
121	        address[] calldata _guardians,
122	        string[] calldata _guardianNames,
123	        TriggerConfig calldata _triggerConfig,
124	        bytes32 _encryptedDataHash
125	    ) external returns (uint256) {
126	        // Validate inputs
127	        if (_beneficiaries.length == 0 || _beneficiaries.length != _percentages.length)
128	            revert InvalidBeneficiaries();
