130	            revert NotEnoughGuardians();
131	
132	        // Validate percentages sum to 100%
133	        uint256 totalPercentage;
134	        for (uint256 i = 0; i < _percentages.length; i++) {
135	            totalPercentage += _percentages[i];
136	        }
137	        if (totalPercentage != 10000) revert InvalidPercentages();
138	
139	        // Create will
140	        uint256 willId = _nextWillId++;
141	
