145	            status: WillStatus.Active,
146	            triggerConfig: _triggerConfig,
147	            lastHeartbeat: block.timestamp,
148	            createdAt: block.timestamp,
149	            executedAt: 0
150	        });
151	
152	        // Add beneficiaries
153	        for (uint256 i = 0; i < _beneficiaries.length; i++) {
154	            if (_beneficiaries[i] == address(0)) revert InvalidAddress();
155	            _willBeneficiaries[willId].push(Beneficiary({
156	                name: _names[i],
157	                wallet: _beneficiaries[i],
158	                percentage: _percentages[i],
159	                delaySeconds: _delaySeconds[i],
160	                claimed: false
161	            }));
162	        }
163	
164	        // Add guardians
165	        for (uint256 i = 0; i < _guardians.length; i++) {
166	            if (_guardians[i] == address(0) || _guardians[i] == msg.sender) revert InvalidAddress();
167	            _willGuardians[willId].push(Guardian({
168	                wallet: _guardians[i],
169	                name: _guardianNames[i],
170	                hasVoted: false,
171	                vote: false,
172	                votedAt: 0
173	            }));
174	            _isGuardian[willId][_guardians[i]] = true;
175	            emit GuardianAdded(willId, _guardians[i]);
176	        }
177	
178	        _ownerWills[msg.sender].push(willId);
179	        emit WillCreated(willId, msg.sender, _encryptedDataHash);
180	
181	        return willId;
182	    }
