206	        if (_isGuardian[_willId][_guardian]) revert(); // Already a guardian
207	
208	        _willGuardians[_willId].push(Guardian({
209	            wallet: _guardian,
210	            name: _name,
211	            hasVoted: false,
212	            vote: false,
213	            votedAt: 0
214	        }));
