220	     * @notice Remove a guardian from a will
221	     * @param _willId Will ID
222	     * @param _guardian Guardian address
223	     */
224	    function removeGuardian(uint256 _willId, address _guardian)
225	        external onlyOwner(_willId) notExecuted(_willId)
226	    {
227	        if (!_isGuardian[_willId][_guardian]) revert NotGuardian();
228	
229	        Guardian[] storage g = _willGuardians[_willId];
230	        for (uint256 i = 0; i < g.length; i++) {
231	            if (g[i].wallet == _guardian) {
232	                if (g[i].hasVoted && g[i].vote) {
233	                    _guardianVotesFor[_willId]--;
234	                }
235	                g[i] = g[g.length - 1];
236	                g.pop();
237	                break;
238	            }
239	        }
240	        _isGuardian[_willId][_guardian] = false;
241	        emit GuardianRemoved(_willId, _guardian);
