244	    /**
245	     * @notice Guardian votes on whether the owner is deceased
246	     * @param _willId Will ID
247	     * @param _isDeceased true if guardian believes owner is deceased
248	     */
249	    function guardianVote(uint256 _willId, bool _isDeceased)
250	        external onlyGuardian(_willId) notExecuted(_willId)
251	    {
252	        Guardian[] storage g = _willGuardians[_willId];
253	        for (uint256 i = 0; i < g.length; i++) {
254	            if (g[i].wallet == msg.sender) {
255	                if (g[i].hasVoted) revert AlreadyVoted();
256	                g[i].hasVoted = true;
257	                g[i].vote = _isDeceased;
258	                g[i].votedAt = block.timestamp;
259	                if (_isDeceased) {
260	                    _guardianVotesFor[_willId]++;
261	                }
262	                break;
263	            }
264	        }
265	        emit GuardianVoted(_willId, msg.sender, _isDeceased, block.timestamp);
266	    }
267	
268	    /**
269	     * @notice Execute will and distribute assets (called by AI Agent)
270	     * @param _willId Will ID
271	     */
272	    function executeWill(uint256 _willId) external {
273	        (bool canExecute, ) = _checkExecutable(_willId);
274	        if (!canExecute) revert();
275	
276	        Will storage will = _wills[_willId];
277	        will.status = WillStatus.Executed;
278	        will.executedAt = block.timestamp;
279	
280	        emit WillExecuted(_willId, block.timestamp);
281	    }
282	
283	    /**
284	     * @notice Distribute ETH to beneficiaries (called by AI Agent or executor)
285	     * @param _willId Will ID
286	     */
287	    function distributeETH(uint256 _willId) external {
288	        if (_wills[_willId].status != WillStatus.Executed) revert NotExecuted();
289	
290	        uint256 balance = address(this).balance;
291	        if (balance == 0) revert NoAssets();
292	
293	        Beneficiary[] storage b = _willBeneficiaries[_willId];
294	        for (uint256 i = 0; i < b.length; i++) {
295	            if (b[i].claimed) continue;
296	            if (b[i].delaySeconds > 0 && block.timestamp < _wills[_willId].executedAt + b[i].delaySeconds) {
297	                continue; // Skip time-locked beneficiaries for now
298	            }
299	
300	            uint256 amount = (balance * b[i].percentage) / 10000;
301	            if (amount > 0) {
302	                b[i].claimed = true;
303	                (bool success, ) = payable(b[i].wallet).call{value: amount}("");
304	                if (!success) revert TransferFailed();
305	                emit AssetsClaimed(_willId, b[i].wallet, amount);
306	            }
307	        }
308	    }
309	
310	    /**
311	     * @notice Distribute ERC-20 tokens to beneficiaries
312	     * @param _willId Will ID
313	     * @param _token ERC-20 token address
314	     */
315	    function distributeERC20(uint256 _willId, address _token) external {
316	        if (_wills[_willId].status != WillStatus.Executed) revert NotExecuted();
317	
318	        // Using IERC20 interface via low-level call for flexibility
319	        // This function would need a real IERC20 import
320	        (bool success, bytes memory data) = _token.staticcall(
321	            abi.encodeWithSignature("balanceOf(address)", address(this))
322	        );
323	        if (!success) revert();
324	        uint256 balance = abi.decode(data, (uint256));
325	        if (balance == 0) revert NoAssets();
326	
327	        Beneficiary[] storage b = _willBeneficiaries[_willId];
328	        for (uint256 i = 0; i < b.length; i++) {
329	            if (b[i].delaySeconds > 0) continue; // Skip delayed beneficiaries
330	
331	            uint256 amount = (balance * b[i].percentage) / 10000;
332	            if (amount > 0) {
333	                (success, ) = _token.call(
334	                    abi.encodeWithSignature("transfer(address,uint256)", b[i].wallet, amount)
335	                );
336	                if (!success) revert TransferFailed();
337	            }
338	        }
339	    }
340	
341	    /**
342	     * @notice Revoke will (only before execution)
343	     * @param _willId Will ID
344	     */
345	    function revokeWill(uint256 _willId) external onlyOwner(_willId) notExecuted(_willId) {
346	        _wills[_willId].status = WillStatus.Revoked;
347	        emit WillRevoked(_willId);
348	    }
349	
350	    /**
351	     * @notice Update will configuration
352	     * @param _willId Will ID
353	     * @param _newHash New IPFS hash (optional)
354	     * @param _newInactivityPeriod New inactivity period (0 to keep unchanged)
355	     */
356	    function updateWill(uint256 _willId, bytes32 _newHash, uint256 _newInactivityPeriod)
357	        external onlyOwner(_willId) notExecuted(_willId)
358	    {
359	        if (_newHash != bytes32(0)) {
360	            _wills[_willId].encryptedDataHash = _newHash;
361	        }
362	        if (_newInactivityPeriod > 0) {
363	            _wills[_willId].triggerConfig.inactivityPeriod = _newInactivityPeriod;
364	        }
365	        emit WillUpdated(_willId);
366	    }
367	
368	    // ============ View Functions ============
369	
370	    /**
371	     * @notice Get will summary
372	     */
373	    function getWill(uint256 _willId) external view returns (Will memory) {
374	        return _wills[_willId];
375	    }
376	
377	    /**
378	     * @notice Get all beneficiaries for a will
379	     */
380	    function getBeneficiaries(uint256 _willId) external view returns (Beneficiary[] memory) {
381	        return _willBeneficiaries[_willId];
382	    }
383	
384	    /**
385	     * @notice Get all guardians for a will
386	     */
387	    function getGuardians(uint256 _willId) external view returns (Guardian[] memory) {
388	        return _willGuardians[_willId];
389	    }
390	
391	    /**
392	     * @notice Get guardian vote status
393	     */
394	    function getGuardianVoteStatus(uint256 _willId) external view returns (uint256 votesFor, uint256 total) {
395	        return (_guardianVotesFor[_willId], _willGuardians[_willId].length);
396	    }
397	
398	    /**
399	     * @notice Check if will is executable (public view, for AI Agent)
400	     * @param _willId Will ID
401	     * @return canExecute Whether execution conditions are met
402	     * @return confidenceScore Confidence score (basis points, 10000 = 100%)
403	     */
404	    function checkExecutable(uint256 _willId) external view returns (bool canExecute, uint256 confidenceScore) {
405	        return _checkExecutable(_willId);
406	    }
407	
408	    /**
409	     * @notice Get all will IDs for an owner
410	     */
411	    function getOwnerWills(address _owner) external view returns (uint256[] memory) {
412	        return _ownerWills[_owner];
413	    }
414	
415	    /**
416	     * @notice Get detailed will status with scores
417	     */
418	    function getWillStatus(uint256 _willId) external view returns (
419	        WillStatus status,
420	        uint256 lastHeartbeat,
421	        uint256 inactivityScore,
422	        uint256 guardianScore,
423	        uint256 guardianVotesFor,
424	        uint256 totalGuardians
425	    ) {
426	        Will storage will = _wills[_willId];
427	        (inactivityScore, guardianScore) = _calculateScores(_willId);
428	        return (
429	            will.status,
430	            will.lastHeartbeat,
431	            inactivityScore,
432	            guardianScore,
433	            _guardianVotesFor[_willId],
434	            _willGuardians[_willId].length
435	        );
436	    }
437	
438	    /**
439	     * @notice Check if an address is guardian for a will
440	     */
441	    function isGuardian(uint256 _willId, address _address) external view returns (bool) {
442	        return _isGuardian[_willId][_address];
443	    }
444	
445	    /**
446	     * @notice Get total number of wills created
447	     */
448	    function totalWills() external view returns (uint256) {
449	        return _nextWillId;
450	    }
451	
452	    // ============ Internal Functions ============
453	
454	    /**
455	     * @notice Check if will is executable
456	     * @param _willId Will ID
457	     * @return canExecute Whether execution conditions are met
458	     * @return confidenceScore Confidence score (basis points, 10000 = 100%)
459	     */
460	    function _checkExecutable(uint256 _willId) internal view returns (bool canExecute, uint256 confidenceScore) {
461	        Will storage will = _wills[_willId];
462	        if (will.status != WillStatus.Active) return (false, 0);
463	
464	        (uint256 inactivityScore, uint256 guardianScore) = _calculateScores(_willId);
465	
466	        // Weighted confidence: 40% inactivity, 40% guardian, 20% oracle (future)
467	        confidenceScore = (inactivityScore * 4000 + guardianScore * 4000) / 10000;
468	        canExecute = confidenceScore >= 7000; // 70% threshold
469	
470	        return (canExecute, confidenceScore);
471	    }
472	
473	    /**
474	     * @notice Calculate inactivity and guardian confidence scores
475	     * @return inactivityScore Score in basis points (0-10000)
476	     * @return guardianScore Guardian consensus score (0-10000)
477	     */
478	    function _calculateScores(uint256 _willId) internal view returns (uint256 inactivityScore, uint256 guardianScore) {
479	        Will storage will = _wills[_willId];
480	
481	        // Inactivity score
482	        if (will.triggerConfig.inactivityPeriod > 0) {
483	            uint256 timeSinceLastHeartbeat = block.timestamp - will.lastHeartbeat;
484	            if (timeSinceLastHeartbeat >= will.triggerConfig.inactivityPeriod) {
485	                inactivityScore = 10000; // Fully inactive
486	            } else {
487	                inactivityScore = (timeSinceLastHeartbeat * 10000) / will.triggerConfig.inactivityPeriod;
488	            }
489	        }
490	
491	        // Guardian score
492	        uint256 totalGuardians = _willGuardians[_willId].length;
493	        if (totalGuardians > 0 && will.triggerConfig.guardianThreshold > 0) {
494	            uint256 votesFor = _guardianVotesFor[_willId];
495	            if (votesFor >= will.triggerConfig.guardianThreshold) {
496	                guardianScore = 10000; // Threshold met
497	            } else if (will.triggerConfig.guardianThreshold > 0) {
498	                guardianScore = (votesFor * 10000) / will.triggerConfig.guardianThreshold;
499	            }
500	        }
501	
502	        return (inactivityScore, guardianScore);
503	    }
504	
505	    // ============ Receive ETH ============
506	
507	    receive() external payable {}
508	}
