// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title EternaWill
 * @notice Core contract for digital will creation, life monitoring, and asset distribution.
 * @dev Manages beneficiaries, guardians, heartbeat mechanism, and execution triggers.
 */

contract EternaWill {
    // ============ Errors ============
    error NotOwner();
    error AlreadyExecuted();
    error NotExecuted();
    error NotGuardian();
    error AlreadyVoted();
    error InvalidBeneficiaries();
    error InvalidPercentages();
    error NoAssets();
    error TransferFailed();
    error NotEnoughGuardians();
    error HeartbeatTooSoon();
    error CannotRevokeAfterDeath();
    error InvalidAddress();

    // ============ Types ============

    enum WillStatus { Active, Executed, Revoked }

    struct Beneficiary {
        string name;
        address wallet;
        uint256 percentage; // Basis points (e.g., 5000 = 50%)
        uint256 delaySeconds; // 0 = immediate, >0 = time-locked
        bool claimed;
    }

    struct Guardian {
        address wallet;
        string name;
        bool hasVoted;
        bool vote; // true = deceased confirmed
        uint256 votedAt;
    }

    struct TriggerConfig {
        uint256 inactivityPeriod; // Seconds without heartbeat before trigger
        uint256 guardianThreshold; // Number of guardian votes needed
        uint256 minGuardians; // Minimum guardians required
        bool useOracle; // Future: external oracle verification
    }

    struct Will {
        address owner;
        bytes32 encryptedDataHash; // IPFS hash of encrypted will document
        WillStatus status;
        TriggerConfig triggerConfig;
        uint256 lastHeartbeat;
        uint256 createdAt;
        uint256 executedAt;
    }

    // ============ State ============

    uint256 private _nextWillId;
    mapping(uint256 => Will) private _wills;
    mapping(uint256 => Beneficiary[]) private _willBeneficiaries;
    mapping(uint256 => Guardian[]) private _willGuardians;
    mapping(uint256 => mapping(address => bool)) private _isGuardian;
    mapping(uint256 => uint256) private _guardianVotesFor;
    mapping(address => uint256[]) private _ownerWills;

    // ============ Events ============

    event WillCreated(uint256 indexed willId, address indexed owner, bytes32 encryptedDataHash);
    event Heartbeat(uint256 indexed willId, address indexed owner, uint256 timestamp);
    event GuardianAdded(uint256 indexed willId, address indexed guardian);
    event GuardianRemoved(uint256 indexed willId, address indexed guardian);
    event GuardianVoted(uint256 indexed willId, address indexed guardian, bool vote, uint256 timestamp);
    event WillExecuted(uint256 indexed willId, uint256 timestamp);
    event WillRevoked(uint256 indexed willId);
    event AssetsClaimed(uint256 indexed willId, address indexed beneficiary, uint256 amount);
    event BeneficiaryUpdated(uint256 indexed willId, address indexed beneficiary);
    event WillUpdated(uint256 indexed willId);

    // ============ Modifiers ============

    modifier onlyOwner(uint256 _willId) {
        if (_wills[_willId].owner != msg.sender) revert NotOwner();
        _;
    }

    modifier notExecuted(uint256 _willId) {
        if (_wills[_willId].status == WillStatus.Executed) revert AlreadyExecuted();
        _;
    }

    modifier onlyGuardian(uint256 _willId) {
        if (!_isGuardian[_willId][msg.sender]) revert NotGuardian();
        _;
    }

    // ============ Core Functions ============

    /**
     * @notice Create a new digital will
     * @param _beneficiaries Array of beneficiary addresses
     * @param _percentages Array of percentages in basis points (50% = 5000)
     * @param _names Array of beneficiary names
     * @param _delaySeconds Array of time-lock delays (0 for immediate)
     * @param _guardians Array of guardian addresses
     * @param _guardianNames Array of guardian names
     * @param _triggerConfig Trigger configuration
     * @param _encryptedDataHash IPFS hash of encrypted will document
     */
    function createWill(
        address[] calldata _beneficiaries,
        uint256[] calldata _percentages,
        string[] calldata _names,
        uint256[] calldata _delaySeconds,
        address[] calldata _guardians,
        string[] calldata _guardianNames,
        TriggerConfig calldata _triggerConfig,
        bytes32 _encryptedDataHash
    ) external returns (uint256) {
        // Validate inputs
        if (_beneficiaries.length == 0 || _beneficiaries.length != _percentages.length)
            revert InvalidBeneficiaries();
        if (_guardians.length < _triggerConfig.minGuardians || _guardians.length < 2)
            revert NotEnoughGuardians();

        // Validate percentages sum to 100%
        uint256 totalPercentage;
        for (uint256 i = 0; i < _percentages.length; i++) {
            totalPercentage += _percentages[i];
        }
        if (totalPercentage != 10000) revert InvalidPercentages();

        // Create will
        uint256 willId = _nextWillId++;

        _wills[willId] = Will({
            owner: msg.sender,
            encryptedDataHash: _encryptedDataHash,
            status: WillStatus.Active,
            triggerConfig: _triggerConfig,
            lastHeartbeat: block.timestamp,
            createdAt: block.timestamp,
            executedAt: 0
        });

        // Add beneficiaries
        for (uint256 i = 0; i < _beneficiaries.length; i++) {
            if (_beneficiaries[i] == address(0)) revert InvalidAddress();
            _willBeneficiaries[willId].push(Beneficiary({
                name: _names[i],
                wallet: _beneficiaries[i],
                percentage: _percentages[i],
                delaySeconds: _delaySeconds[i],
                claimed: false
            }));
        }

        // Add guardians
        for (uint256 i = 0; i < _guardians.length; i++) {
            if (_guardians[i] == address(0) || _guardians[i] == msg.sender) revert InvalidAddress();
            _willGuardians[willId].push(Guardian({
                wallet: _guardians[i],
                name: _guardianNames[i],
                hasVoted: false,
                vote: false,
                votedAt: 0
            }));
            _isGuardian[willId][_guardians[i]] = true;
            emit GuardianAdded(willId, _guardians[i]);
        }

        _ownerWills[msg.sender].push(willId);
        emit WillCreated(willId, msg.sender, _encryptedDataHash);

        return willId;
    }

    /**
     * @notice Send heartbeat to prove the owner is alive
     * @param _willId Will ID
     */
    function checkIn(uint256 _willId) external onlyOwner(_willId) notExecuted(_willId) {
        if (block.timestamp < _wills[_willId].lastHeartbeat + 1 hours) {
            revert HeartbeatTooSoon();
        }
        _wills[_willId].lastHeartbeat = block.timestamp;
        emit Heartbeat(_willId, msg.sender, block.timestamp);
    }

    /**
     * @notice Add a guardian to a will
     * @param _willId Will ID
     * @param _guardian Guardian address
     * @param _name Guardian name
     */
    function addGuardian(uint256 _willId, address _guardian, string calldata _name)
        external onlyOwner(_willId) notExecuted(_willId)
    {
        if (_guardian == address(0) || _guardian == msg.sender) revert InvalidAddress();
        if (_isGuardian[_willId][_guardian]) revert(); // Already a guardian

        _willGuardians[_willId].push(Guardian({
            wallet: _guardian,
            name: _name,
            hasVoted: false,
            vote: false,
            votedAt: 0
        }));
        _isGuardian[_willId][_guardian] = true;
        emit GuardianAdded(_willId, _guardian);
    }

    /**
     * @notice Remove a guardian from a will
     * @param _willId Will ID
     * @param _guardian Guardian address
     */
    function removeGuardian(uint256 _willId, address _guardian)
        external onlyOwner(_willId) notExecuted(_willId)
    {
        if (!_isGuardian[_willId][_guardian]) revert NotGuardian();

        Guardian[] storage g = _willGuardians[_willId];
        for (uint256 i = 0; i < g.length; i++) {
            if (g[i].wallet == _guardian) {
                if (g[i].hasVoted && g[i].vote) {
                    _guardianVotesFor[_willId]--;
                }
                g[i] = g[g.length - 1];
                g.pop();
                break;
            }
        }
        _isGuardian[_willId][_guardian] = false;
        emit GuardianRemoved(_willId, _guardian);
    }

    /**
     * @notice Guardian votes on whether the owner is deceased
     * @param _willId Will ID
     * @param _isDeceased true if guardian believes owner is deceased
     */
    function guardianVote(uint256 _willId, bool _isDeceased)
        external onlyGuardian(_willId) notExecuted(_willId)
    {
        Guardian[] storage g = _willGuardians[_willId];
        for (uint256 i = 0; i < g.length; i++) {
            if (g[i].wallet == msg.sender) {
                if (g[i].hasVoted) revert AlreadyVoted();
                g[i].hasVoted = true;
                g[i].vote = _isDeceased;
                g[i].votedAt = block.timestamp;
                if (_isDeceased) {
                    _guardianVotesFor[_willId]++;
                }
                break;
            }
        }
        emit GuardianVoted(_willId, msg.sender, _isDeceased, block.timestamp);
    }

    /**
     * @notice Execute will and distribute assets (called by AI Agent)
     * @param _willId Will ID
     */
    function executeWill(uint256 _willId) external {
        (bool canExecute, ) = _checkExecutable(_willId);
        if (!canExecute) revert();

        Will storage will = _wills[_willId];
        will.status = WillStatus.Executed;
        will.executedAt = block.timestamp;

        emit WillExecuted(_willId, block.timestamp);
    }

    /**
     * @notice Distribute ETH to beneficiaries (called by AI Agent or executor)
     * @param _willId Will ID
     */
    function distributeETH(uint256 _willId) external {
        if (_wills[_willId].status != WillStatus.Executed) revert NotExecuted();

        uint256 balance = address(this).balance;
        if (balance == 0) revert NoAssets();

        Beneficiary[] storage b = _willBeneficiaries[_willId];
        for (uint256 i = 0; i < b.length; i++) {
            if (b[i].claimed) continue;
            if (b[i].delaySeconds > 0 && block.timestamp < _wills[_willId].executedAt + b[i].delaySeconds) {
                continue; // Skip time-locked beneficiaries for now
            }

            uint256 amount = (balance * b[i].percentage) / 10000;
            if (amount > 0) {
                b[i].claimed = true;
                (bool success, ) = payable(b[i].wallet).call{value: amount}("");
                if (!success) revert TransferFailed();
                emit AssetsClaimed(_willId, b[i].wallet, amount);
            }
        }
    }

    /**
     * @notice Distribute ERC-20 tokens to beneficiaries
     * @param _willId Will ID
     * @param _token ERC-20 token address
     */
    function distributeERC20(uint256 _willId, address _token) external {
        if (_wills[_willId].status != WillStatus.Executed) revert NotExecuted();

        // Using IERC20 interface via low-level call for flexibility
        // This function would need a real IERC20 import
        (bool success, bytes memory data) = _token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(this))
        );
        if (!success) revert();
        uint256 balance = abi.decode(data, (uint256));
        if (balance == 0) revert NoAssets();

        Beneficiary[] storage b = _willBeneficiaries[_willId];
        for (uint256 i = 0; i < b.length; i++) {
            if (b[i].delaySeconds > 0) continue; // Skip delayed beneficiaries

            uint256 amount = (balance * b[i].percentage) / 10000;
            if (amount > 0) {
                (success, ) = _token.call(
                    abi.encodeWithSignature("transfer(address,uint256)", b[i].wallet, amount)
                );
                if (!success) revert TransferFailed();
            }
        }
    }

    /**
     * @notice Revoke will (only before execution)
     * @param _willId Will ID
     */
    function revokeWill(uint256 _willId) external onlyOwner(_willId) notExecuted(_willId) {
        _wills[_willId].status = WillStatus.Revoked;
        emit WillRevoked(_willId);
    }

    /**
     * @notice Update will configuration
     * @param _willId Will ID
     * @param _newHash New IPFS hash (optional)
     * @param _newInactivityPeriod New inactivity period (0 to keep unchanged)
     */
    function updateWill(uint256 _willId, bytes32 _newHash, uint256 _newInactivityPeriod)
        external onlyOwner(_willId) notExecuted(_willId)
    {
        if (_newHash != bytes32(0)) {
            _wills[_willId].encryptedDataHash = _newHash;
        }
        if (_newInactivityPeriod > 0) {
            _wills[_willId].triggerConfig.inactivityPeriod = _newInactivityPeriod;
        }
        emit WillUpdated(_willId);
    }

    // ============ View Functions ============

    /**
     * @notice Get will summary
     */
    function getWill(uint256 _willId) external view returns (Will memory) {
        return _wills[_willId];
    }

    /**
     * @notice Get all beneficiaries for a will
     */
    function getBeneficiaries(uint256 _willId) external view returns (Beneficiary[] memory) {
        return _willBeneficiaries[_willId];
    }

    /**
     * @notice Get all guardians for a will
     */
    function getGuardians(uint256 _willId) external view returns (Guardian[] memory) {
        return _willGuardians[_willId];
    }

    /**
     * @notice Get guardian vote status
     */
    function getGuardianVoteStatus(uint256 _willId) external view returns (uint256 votesFor, uint256 total) {
        return (_guardianVotesFor[_willId], _willGuardians[_willId].length);
    }

    /**
     * @notice Check if will is executable (public view, for AI Agent)
     * @param _willId Will ID
     * @return canExecute Whether execution conditions are met
     * @return confidenceScore Confidence score (basis points, 10000 = 100%)
     */
    function checkExecutable(uint256 _willId) external view returns (bool canExecute, uint256 confidenceScore) {
        return _checkExecutable(_willId);
    }

    /**
     * @notice Get all will IDs for an owner
     */
    function getOwnerWills(address _owner) external view returns (uint256[] memory) {
        return _ownerWills[_owner];
    }

    /**
     * @notice Get detailed will status with scores
     */
    function getWillStatus(uint256 _willId) external view returns (
        WillStatus status,
        uint256 lastHeartbeat,
        uint256 inactivityScore,
        uint256 guardianScore,
        uint256 guardianVotesFor,
        uint256 totalGuardians
    ) {
        Will storage will = _wills[_willId];
        (inactivityScore, guardianScore) = _calculateScores(_willId);
        return (
            will.status,
            will.lastHeartbeat,
            inactivityScore,
            guardianScore,
            _guardianVotesFor[_willId],
            _willGuardians[_willId].length
        );
    }

    /**
     * @notice Check if an address is guardian for a will
     */
    function isGuardian(uint256 _willId, address _address) external view returns (bool) {
        return _isGuardian[_willId][_address];
    }

    /**
     * @notice Get total number of wills created
     */
    function totalWills() external view returns (uint256) {
        return _nextWillId;
    }

    // ============ Internal Functions ============

    /**
     * @notice Check if will is executable
     * @param _willId Will ID
     * @return canExecute Whether execution conditions are met
     * @return confidenceScore Confidence score (basis points, 10000 = 100%)
     */
    function _checkExecutable(uint256 _willId) internal view returns (bool canExecute, uint256 confidenceScore) {
        Will storage will = _wills[_willId];
        if (will.status != WillStatus.Active) return (false, 0);

        (uint256 inactivityScore, uint256 guardianScore) = _calculateScores(_willId);

        // Weighted confidence: 40% inactivity, 40% guardian, 20% oracle (future)
        confidenceScore = (inactivityScore * 4000 + guardianScore * 4000) / 10000;
        canExecute = confidenceScore >= 7000; // 70% threshold

        return (canExecute, confidenceScore);
    }

    /**
     * @notice Calculate inactivity and guardian confidence scores
     * @return inactivityScore Score in basis points (0-10000)
     * @return guardianScore Guardian consensus score (0-10000)
     */
    function _calculateScores(uint256 _willId) internal view returns (uint256 inactivityScore, uint256 guardianScore) {
        Will storage will = _wills[_willId];

        // Inactivity score
        if (will.triggerConfig.inactivityPeriod > 0) {
            uint256 timeSinceLastHeartbeat = block.timestamp - will.lastHeartbeat;
            if (timeSinceLastHeartbeat >= will.triggerConfig.inactivityPeriod) {
                inactivityScore = 10000; // Fully inactive
            } else {
                inactivityScore = (timeSinceLastHeartbeat * 10000) / will.triggerConfig.inactivityPeriod;
            }
        }

        // Guardian score
        uint256 totalGuardians = _willGuardians[_willId].length;
        if (totalGuardians > 0 && will.triggerConfig.guardianThreshold > 0) {
            uint256 votesFor = _guardianVotesFor[_willId];
            if (votesFor >= will.triggerConfig.guardianThreshold) {
                guardianScore = 10000; // Threshold met
            } else if (will.triggerConfig.guardianThreshold > 0) {
                guardianScore = (votesFor * 10000) / will.triggerConfig.guardianThreshold;
            }
        }

        return (inactivityScore, guardianScore);
    }

    // ============ Receive ETH ============

    receive() external payable {}
}
